import ast, sys, os
# report unused imports per module
for base, dirs, names in os.walk('.'):
    for n in names:
        if not n.endswith('.py'):
            continue
        p = os.path.join(base, n)
        src = open(p).read()
        tree = ast.parse(src)
        imported = {}
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for a in node.names:
                    imported[(a.asname or a.name).split('.')[0]] = node.lineno
            elif isinstance(node, ast.ImportFrom):
                for a in node.names:
                    if a.name == '*':
                        continue
                    imported[a.asname or a.name] = node.lineno
        names_used = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Name):
                names_used.add(node.id)
            elif isinstance(node, ast.Attribute):
                pass
        # crude: also scan textual occurrences beyond the import line
        unused = []
        for name, lineno in imported.items():
            occurrences = sum(1 for i, line in enumerate(src.split('\n'), 1)
                              if name in line and i != lineno)
            if occurrences == 0:
                unused.append(name)
        if unused:
            print(p, 'unused imports:', unused)
PYEOF
